1	/* ===== Đoạn giới thiệu điện ảnh: tư thế camera (thuần) — D-045 ===== */
2	export type InVec = [number, number, number];
3	export interface InPose { pos: InVec; target: InVec }
4	export interface InShot { from: InPose; to: InPose }
5	
6	/* smootherstep 6k⁵ − 15k⁴ + 10k³, kẹp [0, 1] */
7	export function inEase(k: number): number {
8	  const x = k < 0 ? 0 : k > 1 ? 1 : k;
9	  return x * x * x * (x * (x * 6 - 15) + 10);
10	}
11	
12	/* Ghi vào pos / target (không cấp phát), nội suy theo inEase(k) */
13	export function inPose(shot: InShot, k: number, pos: InVec, target: InVec): void {
14	  const e = inEase(k);
