// Chụp nhịp intro qua dev server (sửa CONFIG.intro sống, không build). Tạm, không commit.
// TEST_REAL_GPU=1 node shoot.mjs '<json ghi đè CONFIG.intro>' '0,6,8' [w] [h] [prefix] [marks json {i:[..]}]
import fs from 'node:fs';
const ROOT = 'D:/2026 - Tuan/danang-vite/.worktrees/intro-dien-anh/';
const { launch, openApp } = await import('file:///' + ROOT + 'tests/lib.mjs');
const OUT = ROOT + 'tests/screens/intro/';
fs.mkdirSync(OUT, { recursive: true });
const over = JSON.parse(process.argv[2] || '{}');
const list = (process.argv[3] || '0,1,2,3,4,5,6,7,8').split(',').map(Number);
const W = +(process.argv[4] || 1280), H = +(process.argv[5] || 720), pre = process.argv[6] || '';
const mk = JSON.parse(process.argv[7] || '{}');
const ids = ['welcome', 'glider', 'car', 'bike', 'walk', 'daynight', 'dragon', 'swing', 'finale'];
const browser = await launch();
try {
  const mobile = W < 600;
  const { page, errors } = await openApp(browser, 'http://127.0.0.1:5297/?intro', { width: W, height: H, mobile });
  await page.waitForFunction(() => window.__app.intro.active, null, { timeout: 60000 });
  await page.evaluate(async (over) => {
    const m = await import('/src/config.ts');
    const merge = (a, b) => { for (const k of Object.keys(b)) { if (b[k] && typeof b[k] === 'object' && !Array.isArray(b[k]) && a[k] && typeof a[k] === 'object') merge(a[k], b[k]); else a[k] = b[k]; } };
    merge(m.CONFIG.intro, over);
  }, over);
  for (const i of list) {
    const dur = await page.evaluate(async (i) => (await import('/src/config.ts')).CONFIG.intro.scenes[i].dur, i);
    await page.evaluate((i) => window.__app.intro.seek(i), i);
    const marks = mk[i] || [0.6, +(dur / 2).toFixed(1), +(dur - 0.55).toFixed(2)];
    for (const m of marks) {
      await page.waitForFunction(([i, m]) => window.__app.intro.clock.i !== i || window.__app.intro.clock.t >= m || window.__app.intro.clock.done, [i, m], { timeout: 30000 });
      const s = await page.evaluate(() => { const a = window.__app; return { t: +a.intro.clock.t.toFixed(2), cam: a.camera.position.toArray().map((v) => Math.round(v)), sw: a.songHan.ctrl.state, car: a.drive.state ? [a.drive.state.x, a.drive.state.z, a.drive.state.v].map((v) => +v.toFixed(1)) : null, bike: a.bike.state ? [a.bike.state.x, a.bike.state.z, a.bike.state.v, a.bike.state.yaw].map((v) => +v.toFixed(2)) : null, walk: a.stroll.stroll.state ? [a.stroll.stroll.state.x, a.stroll.stroll.state.z].map((v) => +v.toFixed(1)) : null, gl: a.explore.state ? a.explore.state.pos.toArray().map((v) => Math.round(v)) : null }; });
      await page.screenshot({ path: `${OUT}${pre}${i}-${ids[i]}-${m}.png` });
      console.log(`${i} ${ids[i]} @${m}`, JSON.stringify(s));
    }
  }
  if (errors.length) console.log('ERRORS', errors);
} finally { await browser.close(); }

