// Kiểm mục A (nhạc) + C (đường chưa kiểm) của Task 6 D-045 trên dist/, GPU thật. Tạm, không commit.
// TEST_REAL_GPU=1 node task6-check.mjs [phần: a,c1,c2,c3,c4,c5]
import fs from 'node:fs';
const ROOT = 'D:/2026 - Tuan/danang-vite/.worktrees/intro-dien-anh/';
const { serveDir, launch, openApp, frames } = await import('file:///' + ROOT + 'tests/lib.mjs');
const only = (process.argv[2] || 'a,c1,c2,c3,c4,c5').split(',');
const sleep = (ms) => new Promise((ok) => setTimeout(ok, ms));
const problems = [];
const check = (n, ok, extra = '') => { if (!ok) problems.push(n); console.log(`${ok ? 'đạt ' : 'LỖI '} ${n} ${extra}`); };
const fixture = fs.readFileSync(ROOT + 'tests/env-unit/fixture.json', 'utf8');
const srv = await serveDir(ROOT + 'dist');
const browser = await launch();

/* Trang không ?test: chặn Open-Meteo (fixture), GTM, font; ghi lỗi console */
async function openPlain(path, { init = null, glbBlock = false } = {}) {
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push('pageerror: ' + String(e)));
  page.on('console', (m) => { if (m.type() === 'error' && !/fonts\.(googleapis|gstatic)|ERR_FAILED|net::|googletagmanager|open-meteo/.test(m.text())) errors.push(m.text()); });
  await page.route(/fonts\.(googleapis|gstatic)\.com/, (r) => r.abort());
  await page.route(/googletagmanager\.com/, (r) => r.abort());
  await page.route(/api\.open-meteo\.com/, (r) => r.fulfill({ status: 200, contentType: 'application/json', body: fixture }));
  if (glbBlock) await page.route(/\.glb(\?|$)/, (r) => r.abort());
  if (init) await page.addInitScript(init);
  await page.goto(srv.url + path, { waitUntil: 'load', timeout: 180000 });
  await page.waitForFunction(() => document.getElementById('loading')?.classList.contains('done'), null, { timeout: 180000 });
  return { page, errors };
}
const dom = (page) => page.evaluate(() => ({ intro: !document.getElementById('intro').hidden, chooser: !document.getElementById('chooser').hidden, env: document.getElementById('env')?.dataset.mode, notice: (() => { const n = document.getElementById('liveNotice'); return !!n && !n.hidden && getComputedStyle(n).display !== 'none'; })(), snd: document.getElementById('inSound').getAttribute('aria-pressed'), hint: document.getElementById('inSound').classList.contains('in-hint'), music: document.getElementById('btnMusic').getAttribute('aria-pressed'), scene: document.getElementById('intro').dataset.scene || null }));

try {
  if (only.includes('a')) {
    console.log('--- A: nhạc, ?test&intro');
    const { page, errors } = await openApp(browser, srv.url + '?intro', { width: 1280, height: 720 });
    await page.waitForFunction(() => window.__app.intro.active, null, { timeout: 30000 });
    let d = await dom(page);
    check('A gợi ý .in-hint khi nhạc tắt, chưa thao tác', d.hint && d.snd === 'false', JSON.stringify(d));
    await page.mouse.click(640, 300); await sleep(400);
    d = await dom(page);
    const on0 = await page.evaluate(() => window.__app.audio.on);
    check('A ?test: bấm giữa màn hình không tự bật nhạc', !on0 && d.snd === 'false', `on=${on0}`);
    check('A gợi ý tắt sau thao tác đầu', !d.hint);
    await page.click('#inSound'); await sleep(300);
    let r = await page.evaluate(() => ({ on: window.__app.audio.on, snd: document.getElementById('inSound').getAttribute('aria-pressed'), mus: document.getElementById('btnMusic').getAttribute('aria-pressed'), ls: localStorage.getItem('cauRong.music'), active: window.__app.intro.active }));
    check('A bấm #inSound ⇒ audio.on, aria-pressed, #btnMusic', r.on && r.snd === 'true' && r.mus === 'true' && r.active, JSON.stringify(r));
    await page.click('#inSound'); await sleep(300);
    r = await page.evaluate(() => ({ on: window.__app.audio.on, snd: document.getElementById('inSound').getAttribute('aria-pressed'), mus: document.getElementById('btnMusic').getAttribute('aria-pressed'), ls: localStorage.getItem('cauRong.music') }));
    check('A bấm lần nữa ⇒ tắt', !r.on && r.snd === 'false' && r.mus === 'false' && r.ls === 'off', JSON.stringify(r));
    await page.keyboard.press('KeyM'); await sleep(300);
    r = await page.evaluate(() => ({ on: window.__app.audio.on, snd: document.getElementById('inSound').getAttribute('aria-pressed'), active: window.__app.intro.active }));
    check('A phím M ⇒ bật', r.on && r.snd === 'true' && r.active, JSON.stringify(r));
    await page.evaluate(() => window.__app.intro.skip()); await sleep(300);
    r = await page.evaluate(() => ({ on: window.__app.audio.on, active: window.__app.intro.active }));
    check('A kết thúc intro không tắt nhạc', r.on && !r.active, JSON.stringify(r));
    check('A console sạch', errors.length === 0, errors.join(' | '));
    await page.close();

    console.log('--- A: nhạc, trang không ?test');
    const p2 = await openPlain('?intro');
    await p2.page.waitForFunction(() => !document.getElementById('intro').hidden, null, { timeout: 30000 });
    d = await dom(p2.page);
    check('A không ?test: intro phát, nhạc tắt + gợi ý', d.intro && d.snd === 'false' && d.hint, JSON.stringify(d));
    await p2.page.mouse.click(640, 300); await sleep(600);
    d = await dom(p2.page);
    check('A không ?test: một cú bấm giữa màn hình ⇒ nhạc bật', d.snd === 'true' && d.music === 'true' && d.intro, JSON.stringify(d));
    check('A không ?test: console sạch', p2.errors.length === 0, p2.errors.join(' | '));
    await p2.page.close();

    const p3 = await openPlain('?intro', { init: () => { try { localStorage.setItem('cauRong.music', 'off'); } catch {} } });
    await p3.page.waitForFunction(() => !document.getElementById('intro').hidden, null, { timeout: 30000 });
    await p3.page.mouse.click(640, 300); await sleep(600);
    d = await dom(p3.page);
    check('A lựa chọn đã lưu "off": không tự bật', d.snd === 'false' && d.music === 'false', JSON.stringify(d));
    await p3.page.close();
  }
  if (only.includes('c1')) {
    console.log('--- C1: trang không ?test, lần đầu');
    const ctx = await browser.newContext({ viewport: { width: 1280, height: 720 } });
    const page = await ctx.newPage();
    const errors = [];
    page.on('pageerror', (e) => errors.push('pageerror: ' + String(e)));
    page.on('console', (m) => { if (m.type() === 'error' && !/fonts\.(googleapis|gstatic)|ERR_FAILED|net::|googletagmanager|open-meteo/.test(m.text())) errors.push(m.text()); });
    await page.route(/fonts\.(googleapis|gstatic)\.com/, (r) => r.abort());
    await page.route(/googletagmanager\.com/, (r) => r.abort());
    await page.route(/api\.open-meteo\.com/, (r) => r.fulfill({ status: 200, contentType: 'application/json', body: fixture }));
    await page.goto(srv.url, { waitUntil: 'load', timeout: 180000 });
    await page.waitForFunction(() => document.getElementById('loading')?.classList.contains('done'), null, { timeout: 180000 });
    await sleep(800);
    let d = await dom(page);
    check('C1 lần đầu không ?test: intro tự phát', d.intro && !d.chooser, JSON.stringify(d));
    check('C1 trong intro: #liveNotice không hiện', !d.notice);
    const envIn = d.env;
