    const nav = page.waitForNavigation({ waitUntil: 'load', timeout: 60000 }).catch(() => null);
    const clicked = await page.evaluate(() => { const b = document.getElementById('btnIntro'); if (!b) return 'không có'; b.click(); return 'ok'; });
    await nav;
    await page.waitForFunction(() => document.getElementById('loading')?.classList.contains('done'), null, { timeout: 180000 });
    await sleep(1500);
    const r = await page.evaluate(() => ({ mark: window.__mark, intro: !document.getElementById('intro').hidden, url: location.href }));
    check('C4 #btnIntro: trang tải lại và intro phát', clicked === 'ok' && r.mark === undefined && r.intro, `${clicked} ${JSON.stringify(r)}`);
    await page.close();
  }
  if (only.includes('c5')) {
    console.log('--- C5: console sạch ở lượt không ?test, chờ hết intro');
    const { page, errors } = await openPlain('');
    await sleep(20000);
    check('C5 console sạch ≈ 20 s intro không ?test (không "isReady")', errors.length === 0, errors.join(' | '));
    await page.close();
  }
} finally { await browser.close(); srv.close(); }
